return-response.set-body:
@{
        return JsonConvert.SerializeObject(new {
          resource = "{{abw-gateway-url}}/__PATH__/mcp",
          resource_name = "__TITLE__",
          authorization_servers = new[] { "https://login.microsoftonline.com/{{abw-tenant-id}}/v2.0" },
          bearer_methods_supported = new[] { "header" },
          scopes_supported = new[] { "api://__AUDIENCE__/Tools.Read" }
        });
      }
